import sys
sys.setrecursionlimit(100000)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    if n == 0:
        print()
        print()
        print()
        return

    nodes = []
    children = set()

    for i in range(n):
        node_val = int(data[1 + i*3])
        left_val = int(data[1 + i*3 + 1])
        right_val = int(data[1 + i*3 + 2])
        nodes.append((node_val, left_val, right_val))
        if left_val != -1:
            children.add(left_val)
        if right_val != -1:
            children.add(right_val)

    # Find root (node that is not a child of any other node)
    root = None
    for node_val, _, _ in nodes:
        if node_val not in children:
            root = node_val
            break

    if root is None:
        root = nodes[0][0]

    # Create node info dictionary
    node_info = {}
    for node_val, left_val, right_val in nodes:
        node_info[node_val] = (left_val, right_val)

    # Inorder traversal
    def inorder(root_val):
        if root_val == -1:
            return []
        left, right = node_info[root_val]
        return inorder(left) + [root_val] + inorder(right)

    # Preorder traversal
    def preorder(root_val):
        if root_val == -1:
            return []
        left, right = node_info[root_val]
        return [root_val] + preorder(left) + preorder(right)

    # Postorder traversal
    def postorder(root_val):
        if root_val == -1:
            return []
        left, right = node_info[root_val]
        return postorder(left) + postorder(right) + [root_val]

    in_order = inorder(root)
    pre_order = preorder(root)
    post_order = postorder(root)

    print(' '.join(map(str, in_order)))
    print(' '.join(map(str, pre_order)))
    print(' '.join(map(str, post_order)))

if __name__ == "__main__":
    main()
